import { products, testimonials, contacts } from './products.js';

const assets = await fetch('/asset-map.json').then(r=>r.json());
const revisionAssets = await fetch('/revision-assets.json').then(r=>r.ok?r.json():{}).catch(()=>({}));
const app = document.querySelector('#app');
const slug = location.pathname.replace(/^\/+|\/+$/g,'');
const product = products.find(p=>p.slug===slug);
const arrow = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.6"/></svg>';
const diagonal = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12" stroke="currentColor" stroke-width="1.5"/></svg>';
const chevron = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m6 9 6 6 6-6" stroke="currentColor" stroke-width="1.6"/></svg>';
const previousArrow = arrow.replace('viewBox=', 'style="transform:rotate(180deg)" viewBox=');
const check = '<svg width="16" height="16" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m4 10 4 4 8-8" stroke="currentColor" stroke-width="1.6"/></svg>';
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img = p=>assets.products?.[p.slug]||{};
const image = (src,alt,cls='',eager=false)=>`<img src="${esc(src)}" alt="${esc(alt)}" class="${cls}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const button = (text,href,cls='primary')=>`<a class="button ${cls}" href="${href}">${text}${arrow}</a>`;
const money = n=>new Intl.NumberFormat('uk-UA').format(n)+' €';
const additions = p=>revisionAssets.products?.[p.slug]||{};
const label = (n,text)=>`<div class="eyebrow section-label"><span>${n}</span>${text}</div>`;
const sectionHead = (n,kicker,title,extra='')=>`<div class="section-head"><div>${label(n,kicker)}<h2>${title}</h2></div>${extra}</div>`;

function header(){const models=products.map(p=>`<a href="/${p.slug}"><span>${p.name}</span><small>${p.mode}</small>${diagonal}</a>`).join('');return `<header class="header"><div class="container header-inner"><a class="brand" href="/" aria-label="DGSHAPE — головна">${image(assets.logo,'DGSHAPE','',true)}</a><nav class="desktop-nav" aria-label="Основна навігація"><div class="nav-dropdown"><div class="dropdown-heading"><a href="/#frezery">Фрезери</a><button class="models-toggle" aria-label="Показати моделі фрезерів" aria-expanded="false" aria-controls="desktop-models">${chevron}</button></div><div class="models-panel" id="desktop-models" hidden>${models}</div></div><a href="/#tekhnolohii">Технології</a><a href="/#vidhuky">Відгуки</a><a href="/#kontakty">Контакти</a></nav><div class="header-actions"><a class="header-cta" href="${product?'#konsultatsiia':'/#konsultatsiia'}">Отримати пропозицію ${diagonal}</a><button class="menu-toggle" aria-label="Відкрити меню" aria-expanded="false" aria-controls="mobile-nav"><span></span><span></span></button></div></div><nav id="mobile-nav" class="mobile-nav" aria-label="Мобільна навігація" hidden><div class="mobile-models-heading"><a href="/#frezery">Фрезери</a><button class="mobile-models-toggle" aria-label="Показати моделі фрезерів" aria-expanded="false" aria-controls="mobile-models">${chevron}</button></div><div class="mobile-models" id="mobile-models" hidden>${models}</div><a href="/#tekhnolohii">Технології ${arrow}</a><a href="/#vidhuky">Відгуки ${arrow}</a><a href="/#kontakty">Контакти ${arrow}</a><a href="${product?'#konsultatsiia':'/#konsultatsiia'}">Отримати пропозицію ${arrow}</a><p>Yamamoto Dental Group<br>Японські технології. Поруч з вами.</p></nav></header>`;}

function hero(){return `<section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="eyebrow light"><i></i>Японські CAD/CAM-фрезери DGSHAPE</div><h1>Точність, <br>що формує <br><span>результат.</span></h1><p>Рішення для зуботехнічних лабораторій та стоматологічних клінік. Оберіть фрезер під свої матеріали, задачі та обсяги роботи.</p><div class="hero-buttons">${button('Переглянути фрезери','#frezery')}${button('Отримати консультацію','#konsultatsiia','text-light')}</div></div><div class="hero-visual hero-carousel" role="region" aria-roledescription="карусель" aria-label="Чотири фрезери DGSHAPE"><div class="precision-grid" aria-hidden="true"></div><div class="hero-ring" aria-hidden="true"></div><div class="hero-slides">${products.map((p,i)=>`<div class="hero-slide ${!i?'is-active':''}" ${i?'inert':''} aria-hidden="${!!i}"><span class="hero-slide-word" aria-hidden="true">${p.name.replace('DWX-','').replace(' Plus','')}</span>${image(img(p).card||img(p).hero,p.name+' — японський CAD/CAM-фрезер','hero-slide-machine'+(img(p).heroMask?' hero-source-cutout hero-cutout-'+p.slug:''),!i)}<a href="/${p.slug}" class="hero-slide-link"><span><small>${p.mode} · ${p.axes} ос${p.axes===5?'ей':'і'}</small><strong>${p.name}</strong></span><span class="round-arrow">${diagonal}</span></a></div>`).join('')}</div><div class="hero-carousel-controls"><div class="hero-dots">${products.map((p,i)=>`<button class="hero-dot ${!i?'active':''}" aria-label="Показати ${p.name}" aria-pressed="${!i}" data-slide="${i}">0${i+1}</button>`).join('')}</div><div class="carousel-arrows"><button class="hero-prev icon-button" aria-label="Попередній фрезер">${previousArrow}</button><button class="hero-next icon-button" aria-label="Наступний фрезер">${arrow}</button><button class="hero-pause icon-button" aria-label="Призупинити автоматичну зміну моделей" aria-pressed="false"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M8 5v14M16 5v14" stroke="currentColor" stroke-width="2"/></svg></button></div></div></div><div class="hero-bottom"><span>Інженерія Японії. Можливості для вашої практики.</span><a href="#frezery">Відкрийте можливості ${arrow}</a></div></div></section>`;}

function card(p,index){return `<article class="product-card reveal"><a class="card-visual" href="/${p.slug}" aria-label="Детальніше про ${p.name}"><div class="card-top"><span class="tag ${p.slug==='dwx43w'?'wet':''}"><i></i>${p.mode}</span><span class="card-index">0${index+1}</span></div><span class="card-watermark" aria-hidden="true">${p.name.replace('DWX-','').replace(' Plus','')}</span>${image(img(p).card||img(p).hero,p.name)}<span class="visual-link">${diagonal}</span></a><div class="card-content"><div class="card-title"><h3><a href="/${p.slug}">${p.name}</a></h3><span>${p.axes} ос${p.axes===5?'ей':'і'}</span></div><p>${p.description}</p><ul class="card-features">${p.cardFeatures.map(f=>`<li>${check}${f}</li>`).join('')}</ul>${p.price?`<div class="card-price"><strong>${money(p.price.amount)}</strong>${p.installment?'<span>Доступне розтермінування</span>':''}</div>`:''}<a class="text-link" href="/${p.slug}">Детальніше про модель ${arrow}</a></div></article>`;}

function lineup(){return `<section id="frezery" class="section lineup-section"><div class="container">${sectionHead('01','Оберіть свій DGSHAPE','Який фрезер підходить<br>вашим задачам?','<p class="section-intro">Чотири моделі для різних матеріалів, реставрацій та обсягів виробництва. Порівняйте можливості й знайдіть рішення для своєї практики.</p>')}<div class="product-grid">${products.map(card).join('')}</div>${comparison()}</div></section>`;}

const compareRows = [
 ['Тип обробки',['Суха','Мокра','Суха','Суха']],
 ['Кількість осей',['5 осей','4 осі','5 осей','5 осей']],
 ['Інструменти',['15 · автоматична зміна','До 6 інструментів¹','15 · автоматична зміна','15 · автоматична зміна']],
 ['Робота із заготовками',['Диск · C-Clamp','До 6 пін-блоків у холдері','Диск · Open Edge Adapter','До 6 дисків · автоматична зміна']],
 ['Основний фокус',['Широкий вибір сухих матеріалів','Склокераміка та преміли²','Гнучкість і віддалений контроль','Тривалі автоматизовані цикли']]
];
function comparison(){return `<div id="porivniannia" class="comparison-block"><details class="compare-details"><summary><span><small>Усі відмінності в одному місці</small><strong>Порівняти характеристики</strong></span>${chevron}</summary><div class="comparison-content"><p class="comparison-scroll-hint">Прокрутіть таблицю вбік, щоб порівняти всі моделі ${arrow}</p><div class="comparison-desktop" tabindex="0" role="region" aria-label="Порівняння фрезерів, таблицю можна прокручувати горизонтально"><table><caption class="sr-only">Порівняння чотирьох CAD/CAM-фрезерів DGSHAPE</caption><thead><tr><th scope="col">Можливості</th>${products.map(p=>`<th scope="col"><a href="/${p.slug}">${p.name}${diagonal}</a></th>`).join('')}</tr></thead><tbody>${compareRows.map(([k,v])=>`<tr><th scope="row">${k}</th>${v.map(x=>`<td>${x.replace('¹','').replace('²','')}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Вартість</th>${products.map(p=>`<td>${p.price?money(p.price.amount):'За запитом'}</td>`).join('')}</tr></tbody></table></div><p class="footnote">Для обробки титанових премілів на DWX-43W потрібен додатковий холдер, який продається окремо.</p></div></details></div>`;}

function technology(){const points=[['Відкрита система','Свобода вашого цифрового процесу','Працюйте з матеріалами та CAD/CAM-програмами, які підходять вашій практиці. Відкрита архітектура DGSHAPE дозволяє інтегрувати фрезер у наявний процес зі сканером і піччю для спікання.'],['Цифрове виробництво','Великі можливості. Компактний формат.','Серія DWX створена для клінік і зуботехнічних лабораторій. Компактні системи поєднують точність обробки з можливостями цифрового виробництва — від одиночних реставрацій до щоденного потоку робіт.'],['Простота керування','Менше складності у щоденній роботі','Програмна панель VPanel допомагає керувати фрезеруванням із комп’ютера. Зрозумілий інтерфейс, контроль процесу й автоматизовані функції дозволяють зосередитися на якості реставрацій.'],['Японська інженерія','Якість, що починається з виробництва','Стоматологічні рішення DGSHAPE — частина інженерної спадщини Roland DG. В Японії ці фрезери віднесені до медичних приладів і виготовляються за відповідними виробничими стандартами.']];return `<section id="tekhnolohii" class="section technology-section"><div class="container">${sectionHead('02','Технології DGSHAPE','Більше можливостей.<br>Більше свободи.','<p class="section-intro">Спільна філософія всієї лінійки: відкрита архітектура, зручне керування та японська інженерія.</p>')}<div class="brand-technology"><div class="technology-mosaic reveal"><div class="mosaic-title"><span class="eyebrow">DGSHAPE / ROLAND DG</span><h3>Ваш цифровий<br>процес починається тут.</h3></div>${products.map(p=>`<a href="/${p.slug}" class="mosaic-product">${image(img(p).card||img(p).hero,p.name)}<span>${p.name}${diagonal}</span></a>`).join('')}</div><div class="technology-points">${points.map(([k,t,d],i)=>`<article><span>0${i+1} / ${k}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></div></section>`;}

function digitalWorkflow(){return `<section id="tsyfrovyi-protses" class="section workflow-section"><div class="container">${sectionHead('03','Цифровий процес','Від сканування —<br>до готової реставрації.','<p class="section-intro">Як клініка, лабораторія та фрезер працюють разом. Схема допомагає побачити місце DGSHAPE у цифровому виробництві.</p>')}<figure class="workflow-figure"><div class="workflow-figure-heading"><span><i></i>Клініка · Лабораторія · Виробництво</span><span class="workflow-format">CAD / CAM</span></div><button class="workflow-enlarge" aria-label="Збільшити схему цифрового стоматологічного процесу" aria-haspopup="dialog">${image(assets.workflow,'Схема цифрового процесу: скан або відбиток, лабораторія CAD/CAM, вибір способу виготовлення та передача реставрації в клініку','workflow-preview')}<span class="workflow-zoom-label"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="10" cy="10" r="6" stroke="currentColor" stroke-width="1.6"/><path d="m15 15 5 5M10 7v6M7 10h6" stroke="currentColor" stroke-width="1.6"/></svg>Збільшити схему</span></button><figcaption><span>Взаємодія клініки та лабораторії — від отримання даних до виготовлення реставрації.</span><span>Натисніть, щоб роздивитися деталі ${diagonal}</span></figcaption></figure><div class="workflow-steps"><article><span class="workflow-step-number">01</span><h3>Отримання даних</h3><p>Інтраоральний скан або фізичний відбиток, який оцифровують скануванням. Цифровий файл передають до лабораторії.</p></article><article><span class="workflow-step-number">02</span><h3>Проєктування та підготовка</h3><p>У лабораторії реставрацію проєктують у CAD і готують до виготовлення в CAM.</p></article><article><span class="workflow-step-number">03</span><h3>Виготовлення та результат</h3><p>Обирають відповідний спосіб: 3D-друк, сухе або вологе фрезерування. Готову реставрацію передають у клініку.</p></article></div><div class="workflow-role"><p><strong>Місце DGSHAPE у цьому процесі</strong>Фрезери виконують етап виготовлення реставрацій — сухе або вологе фрезерування, залежно від моделі.</p><a class="text-link" href="#frezery">Обрати фрезер ${arrow}</a></div></div></section>`;}

function reviewSlide(r,i,clone=false){const portrait=revisionAssets.portraits?.[r.author];const src=typeof portrait==='string'?portrait:portrait?.src;return `<article class="review-slide" ${clone?'aria-hidden="true" inert':''} data-review="${i}"><div class="review-photo">${src?image(src,r.author):''}<span>Досвід професіоналів</span></div><div class="review-copy"><span class="quote-mark" aria-hidden="true">“</span><p>${esc(r.text)}</p><div class="review-author"><div><h3>${esc(r.author)}</h3><span>${esc(r.organization)} · ${esc(r.city)}</span></div></div><small>${esc(r.attribution||'За відгуком на roland.dental')}</small></div></article>`;}
function reviews(){return `<section id="vidhuky" class="section reviews-section"><div class="container">${sectionHead('04','Досвід професіоналів','Точність, яку цінують<br>у щоденній роботі.','<p class="section-intro">Досвід українських лабораторій та фрезерних центрів, які обрали DGSHAPE.</p>')}<div class="reviews-carousel" role="region" aria-roledescription="карусель" aria-label="Відгуки клієнтів"><div class="reviews-scroll" tabindex="0" aria-label="Гортайте відгуки вбік">${reviewSlide(testimonials.at(-1),testimonials.length-1,true)}${testimonials.map((r,i)=>reviewSlide(r,i)).join('')}${reviewSlide(testimonials[0],0,true)}</div><div class="review-controls"><span class="review-count" aria-live="polite">01 / ${String(testimonials.length).padStart(2,'0')}</span><span class="review-swipe-hint">Досвід, яким діляться</span><div class="carousel-arrows"><button class="review-prev icon-button" aria-label="Попередній відгук">${previousArrow}</button><button class="review-next icon-button" aria-label="Наступний відгук">${arrow}</button></div></div></div></div></section>`;}

function consultation(p){return `<section id="konsultatsiia" class="consultation"><div class="container consultation-grid"><div class="consultation-copy">${label('05','Почнемо з ваших задач')}<h2>${p?'Ваш наступний крок —<br>власний '+p.name+'.':'Підберемо фрезер<br>під ваші задачі.'}</h2><p>Матеріали, типи реставрацій, обсяг роботи.<br>Знайдемо рішення, що відповідає вашій практиці.</p><div class="dealer"><div><strong>Yamamoto Dental Group</strong><span>Компанія-дилер DGSHAPE / Roland</span></div></div><div id="kontakty" class="contact-details"><a href="tel:+380443343834">+38 044 334 38 34 ${diagonal}</a><a href="mailto:info@yamamoto.com.ua">info@yamamoto.com.ua ${diagonal}</a><p>вул. Волинська, 67, м. Київ</p><details><summary>Інші телефони</summary><a href="tel:+380443343835">+38 044 334 38 35</a><a href="tel:+380633742477">+38 063 374 24 77</a><a href="tel:+380954720836">+38 095 472 08 36</a><a href="tel:+380965105301">+38 096 510 53 01</a></details></div></div><form class="consultation-form"><div class="form-heading"><h3>Обговорімо ваше рішення</h3><span class="demo-tag">Тестова форма</span></div><p class="form-note" id="form-note">Демонстрація прототипу. Дані не надсилаються та не зберігаються.</p><div class="field-row"><label>Ім’я<input name="name" autocomplete="given-name" placeholder="Як до вас звертатися?" required maxlength="80"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" placeholder="+380 __ ___ __ __" required inputmode="tel" maxlength="25"></label></div><label>Модель<select name="model" id="model" aria-label="Модель"><option value="help" ${!p?'selected':''}>Потрібна допомога з вибором</option>${products.map(x=>`<option value="${x.slug}" ${p?.slug===x.slug?'selected':''}>${x.name}</option>`).join('')}</select></label><label>Коментар <span class="optional">(необов’язково)</span><textarea name="comment" placeholder="З якими матеріалами та задачами працюєте?" rows="3" maxlength="1500"></textarea></label><button type="submit" class="button primary">Перевірити тестову форму ${arrow}</button><div class="form-feedback" role="status" aria-live="polite"></div><p class="form-bottom">Для реального звернення скористайтеся телефоном або email компанії.</p></form></div></section>`;}

function footer(){return `<footer class="footer"><div class="container footer-top"><a href="/" class="brand" aria-label="DGSHAPE — головна">${image(assets.logo,'DGSHAPE')}</a><span>Японські технології.<br>Точність без компромісів.</span><a href="/#frezery">Усі фрезери ${arrow}</a><a href="/#kontakty">Контакти ${arrow}</a></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Yamamoto Dental Group</span><span>Демонстраційний прототип · Тестові форми</span><a href="#main">Нагору ${previousArrow}</a></div></footer>`;}

function productHero(p){return `<section class="product-hero"><div class="container"><div class="breadcrumbs"><a href="/">Головна</a><span>/</span><a href="/#frezery">Фрезери</a><span>/</span><span>${p.name}</span></div><div class="product-hero-grid"><div class="product-copy"><div class="eyebrow light"><i></i>${p.mode} · ${p.axes} ос${p.axes===5?'ей':'і'}</div>${p.badge?`<span class="product-badge">${esc(p.badge)}</span>`:''}<h1>${p.name.replace(' Plus',' <span class="plus">Plus</span>')}</h1><h2>${p.positioning}</h2><p>${p.description}</p>${button('Отримати пропозицію','#konsultatsiia')}<a class="back-link" href="/#frezery">${previousArrow} Усі фрезери</a></div><div class="product-hero-visual"><div class="hero-ring" aria-hidden="true"></div>${image(img(p).card||img(p).hero,p.name,'',true)}<span class="product-visual-caption">DGSHAPE / Японська інженерія</span></div></div></div></section><nav class="product-subnav" aria-label="Розділи продукту"><div class="container"><strong>${p.name}</strong><a href="#osoblyvosti">Особливості</a>${p.reliability?'<a href="#nadiinist">Надійність</a>':''}<a href="#halereia">Галерея</a><a href="#materialy">Матеріали</a><a href="#kharakterystyky">Характеристики</a><a href="#vartist">Вартість</a><a href="#konsultatsiia">Консультація ${arrow}</a></div></nav>`;}

function productFeatures(p){const details=p.expandedFeatures||p.features;const photos=additions(p).features||[];return `<section id="osoblyvosti" class="section container">${sectionHead('01','Можливості '+p.name,'Створений для<br>вашого результату.')}<div class="product-overview">${(p.overview||[]).map(t=>`<p>${esc(t)}</p>`).join('')}</div><div class="illustrated-features">${details.map((f,i)=>{const photo=photos[i]||null;return `<article class="illustrated-feature reveal ${photo?.kind==='icon'?'is-icon':''}">${photo?`<figure>${image(photo.src,photo.title||p.name)}</figure>`:''}<div class="illustrated-feature-copy"><span class="feature-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p></div></article>`;}).join('')}</div></section>`;}

function productReliability(p){const r=p.reliability;if(!r)return '';return `<section id="nadiinist" class="section reliability-section"><div class="container"><div class="reliability-heading">${label('','Надійність DWX-52Di Plus')}<h2>${r.title}</h2></div><div class="reliability-layout"><figure class="reliability-photo">${image(r.image,p.name+' — фрезерувальна система')}<figcaption>${p.name} · DGSHAPE / Roland DG</figcaption></figure><div class="reliability-content"><div class="reliability-metrics">${r.metrics.map(m=>`<article class="reliability-metric"><strong>${esc(m.value)}</strong><h3>${esc(m.unit)}</h3><p>${esc(m.text)}</p></article>`).join('')}</div><p class="reliability-attribution">${esc(r.attribution)} <a href="${esc(r.source)}" target="_blank" rel="noopener noreferrer">Джерело ${diagonal}</a></p><div class="manufacturer-note"><div><span class="eyebrow">Погляд виробника</span><p>${esc(r.manufacturer.text)}</p></div><div class="manufacturer-author"><strong>${esc(r.manufacturer.name)}</strong><span>${esc(r.manufacturer.role)}</span></div></div></div></div></div></section>`;}

function gallery(p){let images=[...new Set([...(img(p).gallery||[img(p).hero]),...(additions(p).gallery||[])])]; return `<section id="halereia" class="section gallery-section"><div class="container">${sectionHead('02','Ближче до інженерії','Розгляньте кожну деталь.')}<div class="gallery-main"><button class="gallery-enlarge" aria-label="Збільшити фото ${p.name}">${image(images[0],p.name+' — фото 1','gallery-current')}<span class="gallery-zoom">${diagonal} Збільшити</span></button><span class="gallery-counter">01 / ${String(images.length).padStart(2,'0')}</span></div><div class="gallery-thumbs" aria-label="Фотографії ${p.name}">${images.map((src,i)=>`<button class="gallery-thumb ${i===0?'active':''}" data-src="${esc(src)}" data-index="${i}" aria-label="Показати фото ${i+1}" aria-pressed="${i===0}">${image(src,p.name+' — ракурс '+(i+1))}</button>`).join('')}${p.video?`<button class="video-button" data-video="${esc(p.video)}"><span>▷</span>Дивитися відео</button>`:''}</div></div></section>`;}
function materials(p){const restorations=additions(p).restorations||[];const pic=(additions(p).features||[]).find(x=>x.kind!=='icon')||{src:img(p).detail,title:p.name+' — робоча камера'};return `<section id="materialy" class="section materials-section"><div class="container"><div class="materials-layout"><div>${label('03','Матеріали та реставрації')}<h2>Від матеріалу —<br>до реставрації.</h2><p class="section-intro">Оберіть матеріал для вашого цифрового процесу. Можливості ${p.name} допомагають втілювати різні клінічні задачі.</p></div><div><h3 class="minor-heading">Матеріали для обробки</h3><ul class="material-tags">${p.materials.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3 class="minor-heading">Для ваших задач</h3><ul class="task-list">${p.tasks.map(x=>`<li>${check}${esc(x)}</li>`).join('')}</ul>${p.slug==='dwx43w'?'<p class="caveat">Для обробки титанових премілів потрібен додатковий холдер. Він купується окремо.</p>':''}</div></div>${restorations.length?`<div class="restoration-explorer"><figure class="restoration-view">${image(restorations[0].src,restorations[0].name,'restoration-image')}<figcaption><span class="restoration-current-name">${esc(restorations[0].name)}</span><span class="restoration-state">Оберіть реставрацію</span></figcaption></figure><div class="restoration-options"><h3>Ваші реставрації.<br>Ваші можливості.</h3><p>Наведіть на назву для перегляду. Натисніть, щоб зберегти вибір.</p><div class="restoration-buttons">${restorations.map((r,i)=>`<button class="restoration-option ${!i?'active':''}" data-src="${esc(r.src)}" data-name="${esc(r.name)}" aria-pressed="false"><span>${esc(r.name)}</span>${diagonal}</button>`).join('')}</div><button class="restoration-reset" hidden>Зняти фіксацію ${arrow}</button></div></div>`:pic?`<figure class="material-product-photo">${image(pic.src,pic.title||p.name)}<figcaption>${esc(pic.title||p.name)} · ${p.name}</figcaption></figure>`:''}</div></section>`;}
function pricing(p){if(!p.price)return '';const ins=p.installment;return `<section id="vartist" class="section pricing-section"><div class="container">${sectionHead('05','Вартість та придбання','Інвестиція у<br>вашу точність.')}<div class="pricing-grid"><div class="price-card"><span class="eyebrow">${p.name}</span><h3>Ваш наступний фрезер.</h3><div class="price-amount">${p.price.previous?`<del>${money(p.price.previous)}</del>`:''}<strong>${money(p.price.amount)}</strong></div><p>Розрахунок здійснюється у гривні за поточним курсом.</p>${p.slug==='dwx43w'?'<p class="price-included">DGSHAPE CAM у комплекті</p>':''}${button('Отримати пропозицію','#konsultatsiia')}</div>${ins?`<div class="installment-card"><span class="eyebrow">Розтермінування від дилера</span><h3>Почніть зараз.<br>Сплачуйте частинами.</h3><p>Програма Yamamoto Dental Group на ${ins.months} місяців — без переплат та оформлення кредиту.</p><div class="installment-highlights"><div><span>Перший внесок</span><strong>${money(ins.downPayment)}</strong></div><div><span>Щомісяця × ${ins.months}</span><strong>${money(ins.monthly)}</strong></div></div><dl class="installment-details"><div><dt>Вартість за програмою</dt><dd>${money(ins.retail)}</dd></div><div><dt>Сума розтермінування</dt><dd>${money(ins.financed)}</dd></div></dl>${button('Обговорити розтермінування','#konsultatsiia','outline')}</div>`:`<div class="price-support"><span class="eyebrow">Рішення для вашої практики</span><h3>Від вибору —<br>до власного виробництва.</h3><p>Обговоріть із командою Yamamoto Dental Group матеріали, задачі та обсяг робіт. Отримайте пропозицію на ${p.name} з комплектацією для вашого процесу.</p>${image(img(p).card||img(p).hero,p.name)}</div>`}</div></div></section>`;}

function specs(p){return `<section id="kharakterystyky" class="section specs-section"><div class="container specs-layout"><div>${label('04','Технічні дані')}<h2>Точні деталі.<br>Зважений вибір.</h2><p class="section-intro">Ключові характеристики ${p.name}.</p></div><div><dl class="spec-list">${p.specs.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="footnote">Параметри наведені за сторінкою моделі на roland.dental. Остаточну комплектацію та сумісність матеріалів уточнюйте в Yamamoto Dental Group.</p></div></div></section>`;}

app.innerHTML=header()+`<main id="main">`+(product?productHero(product)+productFeatures(product)+productReliability(product)+gallery(product)+materials(product)+specs(product)+pricing(product)+consultation(product):hero()+lineup()+technology()+digitalWorkflow()+reviews()+consultation())+`</main>`+footer()+`<dialog class="lightbox" aria-label="Перегляд зображення"><button class="lightbox-close" aria-label="Закрити перегляд">✕</button><button class="lightbox-prev" aria-label="Попереднє фото">${previousArrow}</button><div class="lightbox-content"></div><button class="lightbox-next" aria-label="Наступне фото">${arrow}</button><p class="lightbox-caption"></p></dialog>`;

const menuButton=document.querySelector('.menu-toggle'), mobileMenu=document.querySelector('.mobile-nav');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Відкрити меню');mobileMenu.hidden=true;document.body.classList.remove('menu-open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));menuButton.setAttribute('aria-label',open?'Відкрити меню':'Закрити меню');mobileMenu.hidden=open;document.body.classList.toggle('menu-open',!open);});
mobileMenu.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus();}});
matchMedia('(min-width: 961px)').addEventListener('change',e=>{if(e.matches)closeMenu();});


const modelsToggle=document.querySelector('.models-toggle'), modelsPanel=document.querySelector('.models-panel'), dropdown=document.querySelector('.nav-dropdown');
function toggleModels(open){modelsToggle.setAttribute('aria-expanded',String(open));modelsPanel.hidden=!open;}
modelsToggle.addEventListener('click',()=>toggleModels(modelsToggle.getAttribute('aria-expanded')!=='true'));
dropdown.addEventListener('mouseenter',()=>toggleModels(true));
dropdown.addEventListener('mouseleave',()=>{if(!dropdown.contains(document.activeElement))toggleModels(false);});
dropdown.addEventListener('focusout',()=>requestAnimationFrame(()=>{if(!dropdown.contains(document.activeElement))toggleModels(false);}));
document.addEventListener('click',e=>{if(!dropdown.contains(e.target))toggleModels(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const restore=modelsPanel.contains(document.activeElement);toggleModels(false);if(restore)modelsToggle.focus();}});
const mobileModelsToggle=document.querySelector('.mobile-models-toggle'),mobileModels=document.querySelector('.mobile-models');
mobileModelsToggle.addEventListener('click',()=>{const open=mobileModelsToggle.getAttribute('aria-expanded')!=='true';mobileModelsToggle.setAttribute('aria-expanded',String(open));mobileModels.hidden=!open;});

const heroSlides=[...document.querySelectorAll('.hero-slide')],heroDots=[...document.querySelectorAll('.hero-dot')];let heroIndex=0,heroTimer,heroPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
function changeHero(i){heroIndex=(i+heroSlides.length)%heroSlides.length;heroSlides.forEach((s,j)=>{s.classList.toggle('is-active',j===heroIndex);s.setAttribute('aria-hidden',String(j!==heroIndex));s.inert=j!==heroIndex;heroDots[j].classList.toggle('active',j===heroIndex);heroDots[j].setAttribute('aria-pressed',String(j===heroIndex));});}
function startHero(){clearInterval(heroTimer);if(heroSlides.length&&!heroPaused&&!document.hidden)heroTimer=setInterval(()=>changeHero(heroIndex+1),1500);}
if(heroSlides.length){document.querySelector('.hero-prev').addEventListener('click',()=>{changeHero(heroIndex-1);startHero();});document.querySelector('.hero-next').addEventListener('click',()=>{changeHero(heroIndex+1);startHero();});heroDots.forEach((b,i)=>b.addEventListener('click',()=>{changeHero(i);startHero();}));const pause=document.querySelector('.hero-pause');function updatePause(){pause.setAttribute('aria-pressed',String(heroPaused));pause.setAttribute('aria-label',heroPaused?'Увімкнути автоматичну зміну моделей':'Призупинити автоматичну зміну моделей');}pause.addEventListener('click',()=>{heroPaused=!heroPaused;updatePause();startHero();});const region=document.querySelector('.hero-carousel');region.addEventListener('mouseenter',()=>clearInterval(heroTimer));region.addEventListener('mouseleave',startHero);region.addEventListener('focusin',()=>clearInterval(heroTimer));region.addEventListener('focusout',e=>{if(!region.contains(e.relatedTarget))startHero();});document.addEventListener('visibilitychange',startHero);updatePause();startHero();}

const reviewTrack=document.querySelector('.reviews-scroll');
if(reviewTrack){const slides=[...reviewTrack.children];let reviewPosition=1,scrollTimer;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const offset=i=>slides[i].offsetLeft-slides[0].offsetLeft;const count=document.querySelector('.review-count');function reviewGo(i,behavior='smooth'){i=Math.max(0,Math.min(i,slides.length-1));reviewPosition=i;reviewTrack.scrollTo({left:offset(i),behavior:reduce?'instant':behavior});}function settleReview(){let nearest=slides.reduce((best,s,i)=>Math.abs(offset(i)-reviewTrack.scrollLeft)<Math.abs(offset(best)-reviewTrack.scrollLeft)?i:best,0);if(nearest===0){nearest=testimonials.length;reviewGo(nearest,'instant');}else if(nearest===slides.length-1){nearest=1;reviewGo(nearest,'instant');}reviewPosition=nearest;count.textContent=`${String(Number(slides[nearest].dataset.review)+1).padStart(2,'0')} / ${String(testimonials.length).padStart(2,'0')}`;slides.forEach((s,i)=>{const active=i===nearest;s.setAttribute('aria-hidden',String(!active));s.inert=!active;});}document.querySelector('.review-prev').addEventListener('click',()=>{if(reviewPosition<=0||reviewPosition>=slides.length-1)settleReview();reviewGo(reviewPosition-1);});document.querySelector('.review-next').addEventListener('click',()=>{if(reviewPosition<=0||reviewPosition>=slides.length-1)settleReview();reviewGo(reviewPosition+1);});reviewTrack.addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(settleReview,160);},{passive:true});reviewTrack.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();reviewGo(reviewPosition+(e.key==='ArrowRight'?1:-1));}});new ResizeObserver(()=>reviewGo(Math.max(1,Math.min(reviewPosition,testimonials.length)),'instant')).observe(reviewTrack);requestAnimationFrame(()=>{reviewGo(1,'instant');settleReview();});}

const explorer=document.querySelector('.restoration-explorer');
if(explorer){const options=[...explorer.querySelectorAll('.restoration-option')],preview=explorer.querySelector('.restoration-image'),caption=explorer.querySelector('.restoration-current-name'),state=explorer.querySelector('.restoration-state'),reset=explorer.querySelector('.restoration-reset');let pinned=null;function show(b){preview.src=b.dataset.src;preview.alt=b.dataset.name;caption.textContent=b.dataset.name;options.forEach(x=>x.classList.toggle('active',x===b));}options.forEach(b=>{b.addEventListener('mouseenter',()=>{if(!pinned&&matchMedia('(hover: hover)').matches)show(b);});b.addEventListener('focus',()=>{if(!pinned)show(b);});b.addEventListener('click',()=>{pinned=b;show(b);options.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));state.textContent='Вибір зафіксовано';reset.hidden=false;});});explorer.querySelector('.restoration-buttons').addEventListener('mouseleave',()=>{if(pinned)show(pinned);});reset.addEventListener('click',()=>{pinned=null;options.forEach(x=>x.setAttribute('aria-pressed','false'));reset.hidden=true;state.textContent='Оберіть реставрацію';show(options[0]);options[0].focus();});}

document.querySelector('form').addEventListener('submit',e=>{e.preventDefault(); const form=e.currentTarget;const chosen=form.elements.model.selectedOptions[0].textContent;form.querySelector('.form-feedback').textContent=`Поля заповнено. Обрана модель: ${chosen}. Це тестова форма: заявку не надіслано. Для консультації зателефонуйте або напишіть компанії.`;});

const thumbs=[...document.querySelectorAll('.gallery-thumb')];let currentIndex=0;
function setImage(i){currentIndex=(i+thumbs.length)%thumbs.length;const current=thumbs[currentIndex];const main=document.querySelector('.gallery-current');if(main){main.src=current.dataset.src;main.alt=`${product.name} — фото ${currentIndex+1}`;}document.querySelector('.gallery-counter').textContent=`${String(currentIndex+1).padStart(2,'0')} / ${String(thumbs.length).padStart(2,'0')}`;thumbs.forEach((b,j)=>{b.classList.toggle('active',j===currentIndex);b.setAttribute('aria-pressed',String(j===currentIndex));});}
thumbs.forEach((b,i)=>b.addEventListener('click',()=>setImage(i)));
const dialog=document.querySelector('.lightbox');let videoMode=false;
function showDialogImage(){dialog.querySelector('.lightbox-content').innerHTML=image(thumbs[currentIndex].dataset.src,product.name+' — збільшене фото');dialog.querySelector('.lightbox-caption').textContent=`${product.name} · ${currentIndex+1} / ${thumbs.length}`;}
document.querySelector('.gallery-enlarge')?.addEventListener('click',()=>{videoMode=false;showDialogImage();dialog.classList.remove('video-mode');dialog.showModal();document.body.classList.add('dialog-open');});
function closeDialog(){dialog.close();}
dialog.querySelector('.lightbox-close').addEventListener('click',closeDialog);
dialog.addEventListener('close',()=>{dialog.querySelector('.lightbox-content').innerHTML='';dialog.classList.remove('workflow-mode');dialog.setAttribute('aria-label','Перегляд зображення');document.body.classList.remove('dialog-open');});
dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog();});
function moveImage(step){if(!videoMode&&thumbs.length){setImage(currentIndex+step);showDialogImage();}}
dialog.querySelector('.lightbox-prev').addEventListener('click',()=>moveImage(-1));dialog.querySelector('.lightbox-next').addEventListener('click',()=>moveImage(1));
dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')moveImage(-1);if(e.key==='ArrowRight')moveImage(1);});
document.querySelector('.workflow-enlarge')?.addEventListener('click',()=>{videoMode=false;dialog.classList.remove('video-mode');dialog.classList.add('workflow-mode');dialog.setAttribute('aria-label','Схема цифрового стоматологічного процесу');const detail=matchMedia('(max-width: 700px)').matches;dialog.querySelector('.lightbox-content').innerHTML=`<div class="workflow-dialog-toolbar"><p>Сканування · CAD/CAM · Виготовлення</p><div role="group" aria-label="Масштаб схеми"><button class="workflow-fit" aria-pressed="${!detail}">Вписати</button><button class="workflow-detail" aria-pressed="${detail}">Деталі</button></div></div><div class="workflow-zoom-scroll ${detail?'is-detail':''}" tabindex="0" role="region" aria-label="Схема, яку можна прокручувати вбік">${image(assets.workflow,'Повна схема цифрового стоматологічного процесу: клініка, сканування, лабораторія CAD/CAM, альтернативні способи виготовлення та готова реставрація')}</div>`;const scroll=dialog.querySelector('.workflow-zoom-scroll'),fit=dialog.querySelector('.workflow-fit'),details=dialog.querySelector('.workflow-detail');function setDetail(on){scroll.classList.toggle('is-detail',on);fit.setAttribute('aria-pressed',String(!on));details.setAttribute('aria-pressed',String(on));dialog.querySelector('.lightbox-caption').textContent=on?'Прокручуйте схему вбік і вниз, щоб роздивитися деталі.':'Загальний огляд цифрового процесу. Оберіть «Деталі» для збільшення.';}fit.addEventListener('click',()=>setDetail(false));details.addEventListener('click',()=>setDetail(true));setDetail(detail);dialog.showModal();document.body.classList.add('dialog-open');});

document.querySelector('.video-button')?.addEventListener('click',e=>{videoMode=true;dialog.classList.add('video-mode');dialog.querySelector('.lightbox-content').innerHTML=`<iframe title="Відео ${product.name}" src="${esc(e.currentTarget.dataset.video)}" allow="fullscreen; encrypted-media; picture-in-picture" allowfullscreen></iframe>`;dialog.querySelector('.lightbox-caption').textContent='Відео з оригінальної сторінки моделі';dialog.showModal();document.body.classList.add('dialog-open');});

if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}});},{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('will-reveal');observer.observe(el);});}
if(location.hash){requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView());}
